# pts1_connector.py
import time, json, socket, subprocess
from datetime import datetime
import requests
import os, sys

ERP = "http://localhost:8080"
API_KEY = "24005ddb99b6ec9"
API_SECRET = "44f0cde25a27d1d"
DOCTYPE = "PTS1 Test"




PC_NAME = socket.gethostname()
POLL_SECONDS = 1
RUN_TIMEOUT_SEC = 120   # kill test if stuck

PYTHON_EXE = "python"

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
PYTHON_EXE = sys.executable
TEST_SCRIPT = os.path.join(BASE_DIR, "actual_test.py")



def headers():
    return {"Authorization": f"token {API_KEY}:{API_SECRET}"}

def now():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def get_queued_jobs():
    params = {
        "fields": '["name","pcb_serial_no","target_pc","test_status","locked_by","abort_requested"]',
        "filters": f'[["{DOCTYPE}","test_status","=","Queued"],["{DOCTYPE}","target_pc","=","{PC_NAME}"]]',
        "order_by": "creation asc",
        "limit_page_length": 5
    }
    r = requests.get(f"{ERP}/api/resource/{DOCTYPE}", headers=headers(), params=params, timeout=10)
    r.raise_for_status()
    return r.json().get("data", [])

def get_doc(name):
    r = requests.get(f"{ERP}/api/resource/{DOCTYPE}/{name}", headers=headers(), timeout=10)
    r.raise_for_status()
    return r.json()["data"]

def update_doc(name, payload):
    r = requests.put(f"{ERP}/api/resource/{DOCTYPE}/{name}", headers=headers(), json=payload, timeout=10)
    r.raise_for_status()

def try_lock(jobname):
    # simple lock: set locked_by if empty and move to Running
    doc = get_doc(jobname)
    if doc.get("test_status") != "Queued":
        return False
    if doc.get("locked_by"):
        return False

    update_doc(jobname, {
        "locked_by": PC_NAME,
        "locked_at": now(),
        "test_status": "Running",
        "test_started_at": now(),
        "test_result": "Pending",
        "current_step": "START",
        "progress_pct": 0,
        "error_message": "",
        "live_log": f"Locked by {PC_NAME} at {now()}\n",
        "result_json": ""
    })
    return True

def tail_limit(s, max_chars=12000):
    return (s or "")[-max_chars:]

def run_test_stream(jobname, serial):
    cmd = [PYTHON_EXE, TEST_SCRIPT, "--serial", serial, "--job", jobname]
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)

    live_log = ""
    metrics = {}
    start_t = time.time()
    last_push = 0.0

    while True:
        # Abort support (poll ERP flag occasionally)
        if int(time.time() - start_t) % 2 == 0:
            doc = get_doc(jobname)
            if doc.get("abort_requested"):
                p.terminate()
                update_doc(jobname, {
                    "test_status": "Failed",
                    "test_result": "Fail",
                    "test_completed_at": now(),
                    "error_message": "Aborted by operator",
                    "live_log": tail_limit(live_log + "ABORT requested\n")
                })
                return

        # Timeout
        if time.time() - start_t > RUN_TIMEOUT_SEC:
            p.kill()
            update_doc(jobname, {
                "test_status": "Failed",
                "test_result": "Fail",
                "test_completed_at": now(),
                "error_message": f"Timeout after {RUN_TIMEOUT_SEC}s",
                "live_log": tail_limit(live_log + f"TIMEOUT after {RUN_TIMEOUT_SEC}s\n")
            })
            return

        line = p.stdout.readline() if p.stdout else ""
        if line:
            line = line.strip()
            if line:
                live_log = tail_limit(live_log + line + "\n")
                payload = {"live_log": live_log}

                try:
                    evt = json.loads(line)
                except Exception:
                    evt = {"event": "LOG", "message": line}

                if evt.get("event") == "STEP":
                    payload["current_step"] = evt.get("name", "")
                    payload["progress_pct"] = int(evt.get("pct", 0))

                elif evt.get("event") == "METRIC":
                    for k, v in evt.items():
                        if k != "event":
                            metrics[k] = v
                    payload["result_json"] = json.dumps(metrics, indent=2)

                elif evt.get("event") == "DONE":
                    result = evt.get("result", "Fail")
                    payload["test_status"] = "Completed" if result == "Pass" else "Failed"
                    payload["test_result"] = result
                    payload["test_completed_at"] = now()

                # throttle update
                t = time.time()
                if (t - last_push) > 0.8 or evt.get("event") in ("STEP", "DONE"):
                    update_doc(jobname, payload)
                    last_push = t
        else:
            # no line -> check if process ended
            rc = p.poll()
            if rc is not None:
                # process ended
                if rc == 0:
                    update_doc(jobname, {
                        "test_status": "Completed",
                        "test_result": "Pass",
                        "test_completed_at": now(),
                        "live_log": live_log
                    })
                else:
                    update_doc(jobname, {
                        "test_status": "Failed",
                        "test_result": "Fail",
                        "test_completed_at": now(),
                        "error_message": f"Exit code {rc}",
                        "live_log": live_log
                    })
                return

def main():
    print(f"[connector] PC_NAME={PC_NAME} polling {ERP}")
    backoff = 1
    while True:
        try:
            jobs = get_queued_jobs()
            if not jobs:
                time.sleep(POLL_SECONDS)
                backoff = 1
                continue

            jobname = jobs[0]["name"]
            serial = jobs[0].get("pcb_serial_no") or "NA"

            if not try_lock(jobname):
                time.sleep(0.5)
                continue

            print("[connector] locked & running", jobname, serial)
            run_test_stream(jobname, serial)
            print("[connector] finished", jobname)
            backoff = 1

        except Exception as e:
            print("[connector] error:", e)
            time.sleep(backoff)
            backoff = min(backoff * 2, 10)

if __name__ == "__main__":
    main()
